17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (hasReachedDailyRegistrationLimit()) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        owner.setCity(resolveCity(owner.getCity()));
115	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
116	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
117	        this.clinicService.saveOwner(owner);
118	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
119	        headers.setLocation(UriComponentsBuilder.newInstance()
120	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
121	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
127	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
128	        if (currentOwner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        currentOwner.setAddress(ownerFieldsDto.getAddress());
132	        currentOwner.setCity(ownerFieldsDto.getCity());
133	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
134	        currentOwner.setLastName(ownerFieldsDto.getLastName());
135	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
136	        this.clinicService.saveOwner(currentOwner);
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Transactional
142	    @Override
143	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        this.clinicService.deleteOwner(owner);
149	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
155	        Owner owner = this.clinicService.findOwnerById(ownerId);
156	        if (owner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        HttpHeaders headers = new HttpHeaders();
160	        Pet pet = petMapper.toPet(petFieldsDto);
161	        owner.setId(ownerId);
162	        pet.setOwner(owner);
163	        pet.getType().setName(null);
164	        this.clinicService.savePet(pet);
165	        PetDto petDto = petMapper.toPetDto(pet);
166	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
167	            .buildAndExpand(pet.getId()).toUri());
168	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
174	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
175	        if (currentOwner != null) {
176	            Pet currentPet = this.clinicService.findPetById(petId);
177	            if (currentPet != null) {
178	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
179	                currentPet.setName(petFieldsDto.getName());
180	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
181	                this.clinicService.savePet(currentPet);
182	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
183	            }
184	        }
185	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
191	        HttpHeaders headers = new HttpHeaders();
192	        Visit visit = visitMapper.toVisit(visitFieldsDto);
193	        Pet pet = new Pet();
194	        pet.setId(petId);
195	        visit.setPet(pet);
196	        this.clinicService.saveVisit(visit);
197	        VisitDto visitDto = visitMapper.toVisitDto(visit);
198	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
199	            .buildAndExpand(visit.getId()).toUri());
200	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
201	    }
202	
203	
204	    /**
205	     * The maximum number of owners that may be registered on any single calendar day.
206	     */
207	    private static final long MAX_DAILY_REGISTRATIONS = 20;
208	
209	    /**
210	     * Determines whether the daily owner-registration limit has already been reached. Owners are
211	     * counted by their {@link Owner#getRegistrationDate() registration date}, so once
212	     * {@value #MAX_DAILY_REGISTRATIONS} owners have been registered with today's date, no further
213	     * owners may be created today.
214	     *
215	     * @return {@code true} if today's registration limit has been reached
216	     */
217	    private boolean hasReachedDailyRegistrationLimit() {
218	        LocalDate today = LocalDate.now();
219	        long registeredToday = this.clinicService.findAllOwners().stream()
220	            .filter(existing -> today.equals(existing.getRegistrationDate()))
221	            .count();
222	        return registeredToday >= MAX_DAILY_REGISTRATIONS;
223	    }
224	
225	    /**
226	     * Builds the customer code for a newly created owner, formatted as
227	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
228	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
229	     *
230	     * @param city the city of the new owner
231	     * @return the assigned customer code
232	     */
233	    private String nextCustomerCode(String city) {
234	        long ownersInCity = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> Objects.equals(
236	                normalize(existing.getCity()), normalize(city)))
237	            .count();
238	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
239	    }
240	
241	    /**
242	     * Resolves the city to store for a newly created owner. The city is title-cased (so
243	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
244	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
245	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
246	     * surrounding or repeated whitespace.
247	     *
248	     * @param city the city supplied for the new owner, may be {@code null}
249	     * @return the city to store, or {@code null} if the input was {@code null}
250	     */
251	    private String resolveCity(String city) {
252	        if (city == null) {
253	            return null;
254	        }
255	        String normalized = normalize(city);
256	        if (!normalized.isEmpty()) {
257	            for (Owner existing : this.clinicService.findAllOwners()) {
258	                if (normalized.equals(normalize(existing.getCity()))) {
259	                    return existing.getCity();
260	                }
261	            }
262	        }
263	        return toTitleCase(city);
264	    }
265	
266	    /**
267	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
268	     * and lower-casing the remaining letters, preserving the original whitespace. For example
269	     * {@code "new  YORK"} becomes {@code "New  York"}.
270	     *
271	     * @param value the raw value, never {@code null}
272	     * @return the title-cased value
273	     */
274	    private static String toTitleCase(String value) {
275	        StringBuilder result = new StringBuilder(value.length());
276	        boolean startOfWord = true;
277	        for (int i = 0; i < value.length(); i++) {
278	            char c = value.charAt(i);
279	            if (Character.isWhitespace(c)) {
280	                startOfWord = true;
281	                result.append(c);
282	            } else if (startOfWord) {
283	                result.append(Character.toTitleCase(c));
284	                startOfWord = false;
285	            } else {
286	                result.append(Character.toLowerCase(c));
287	            }
288	        }
289	        return result.toString();
290	    }
291	
292	    /**
293	     * Determines whether the given telephone number is already used by any other owner.
294	     *
295	     * @param owner the candidate owner
296	     * @return {@code true} if an owner with the same telephone number already exists in the data store
297	     */
298	    private boolean isDuplicateOwner(Owner owner) {
299	        return this.clinicService.findAllOwners().stream()
300	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
301	    }
302	
303	    /**
304	     * Determines whether the given email address is already used by any other owner. An owner
305	     * without an email address is never considered a duplicate on this criterion. Email addresses
306	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
307	     * surrounding or repeated whitespace.
308	     *
309	     * @param owner the candidate owner
310	     * @return {@code true} if the owner provides an email already used by an existing owner
311	     */
312	    private boolean isDuplicateEmail(Owner owner) {
313	        String email = normalize(owner.getEmail());
314	        if (email.isEmpty()) {
315	            return false;
316	        }
317	        return this.clinicService.findAllOwners().stream()
318	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
319	    }
320	
321	    /**
322	     * Normalizes a telephone number to digits only by stripping spaces, dashes and parentheses, so
323	     * that a value such as {@code "(613) 555-0100"} is stored and compared as {@code "6135550100"}.
324	     * This is applied before an owner is stored and before the telephone-uniqueness check, so two
325	     * differently formatted representations of the same number are treated as duplicates. A
326	     * {@code null} value is returned unchanged.
327	     *
328	     * @param telephone the raw telephone number, may be {@code null}
329	     * @return the digits-only telephone number, or {@code null} if the input was {@code null}
330	     */
331	    private static String normalizeTelephone(String telephone) {
332	        if (telephone == null) {
333	            return null;
334	        }
335	        return telephone.replaceAll("[\\s()-]", "");
336	    }
337	
338	    /**
339	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
340	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
341	     * collapsed to a single space and the result is lower-cased. This is what makes
342	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
343	     * duplicates. A {@code null} value normalizes to the empty string.
344	     *
345	     * @param value the raw value, may be {@code null}
346	     * @return the normalized value, never {@code null}
347	     */
348	    private static String normalize(String value) {
349	        if (value == null) {
350	            return "";
351	        }
352	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
358	        Owner owner = this.clinicService.findOwnerById(ownerId);
359	        if (owner != null) {
360	            Pet pet = owner.getPet(petId);
361	            if (pet != null) {
362	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
363	            }
364	        }
365	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
366	    }
367	}
